<!-- App.svelte -->
<script>
    import { throttle } from "./throttle.svelte.js";

    let onclickCount = $state(0);
    let attachCount = $state(0);

    function onAttach() {
        attachCount++;
    }

    function handleClick() {
        onclickCount++;
        console.log(`[onclick] fired #${onclickCount}`);
    }
